import { Group, Mesh, PlaneGeometry, CylinderGeometry, TorusKnotGeometry, CircleGeometry, MeshPhysicalNodeMaterial, MeshBasicNodeMaterial, DoubleSide, AdditiveBlending, Vector2 } from 'three/webgpu';
import { uv, vec2, float, vec3, vec4, mix, smoothstep, positionGeometry, uniform, time, sin, cos, length, saturate } from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const group = new Group();

  // ----- Backdrop Gradient Plane -----
  const gradBackdrop = new PlaneGeometry(7, 6);
  // TSL node for vertical gradient using gradientStops
  const gradStops = config.visual?.gradientStops || [
    { at: 0, hex: '#0b0b10' },
    { at: 0.7, hex: '#101017' },
    { at: 1, hex: '#16161d' }
  ];
  // Convert hex to vec3
  const hexToVec3 = (hex) => {
    const r = parseInt(hex.slice(1,3), 16) / 255;
    const g = parseInt(hex.slice(3,5), 16) / 255;
    const b = parseInt(hex.slice(5,7), 16) / 255;
    return vec3(r, g, b);
  };
  const color0 = hexToVec3(gradStops[0].hex);
  const color1 = hexToVec3(gradStops[1].hex);
  const color2 = hexToVec3(gradStops[2].hex);
  const posY = positionGeometry.y; // -3 to 3
  const t = (posY.add(3)).div(6); // 0 to 1
  const mixA = smoothstep(gradStops[0].at, gradStops[1].at, t);
  const mixB = smoothstep(gradStops[1].at, gradStops[2].at, t);
  const gradColor = mix(color0, color1, mixA);
  const finalColor = mix(gradColor, color2, mixB);
  const gradMat = new MeshBasicNodeMaterial();
  gradMat.colorNode = finalColor;
  gradMat.side = DoubleSide;
  const backdrop = new Mesh(gradBackdrop, gradMat);
  backdrop.position.set(0, 0, -3);
  backdrop.name = 'backdrop';
  group.add(backdrop);

  // ----- Pedestal -----
  // approximate chamfer: radiusTop slightly smaller than radiusBottom
  const pedRadius = 1.1;
  const pedHeight = 0.5;
  const chamfer = 0.03;
  const pedGeo = new CylinderGeometry(pedRadius - chamfer, pedRadius, pedHeight, 48);
  const pedMat = new MeshPhysicalNodeMaterial({
    color: '#14141a',
    roughness: 0.7,
    metalness: 0.35,
    envMapIntensity: 0.7
  });
  const pedestal = new Mesh(pedGeo, pedMat);
  pedestal.position.set(0, -0.35, 0);
  pedestal.name = 'pedestal';
  group.add(pedestal);

  // ----- Torus Knot -----
  const knotGeo = new TorusKnotGeometry(0.7, 0.22, 220, 36);
  const knotMat = new MeshPhysicalNodeMaterial({
    color: '#e8ecf2',
    roughness: 0.55,
    metalness: 0.55,
    clearcoat: 0.22,
    clearcoatRoughness: 0.35,
    anisotropy: 0.9,
    anisotropyRotation: Math.PI / 2, // rotate 90 deg
    envMapIntensity: 0.7,
    metalness: 0.55
  });
  const knot = new Mesh(knotGeo, knotMat);
  knot.position.set(0, 0.4, 0);
  knot.name = 'knot';
  group.add(knot);

  // Load roughness map from imageUrl
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.encoding = ctx.THREE?.sRGBEncoding || 3001; // approximate
      knotMat.roughnessMap = tex;
      knotMat.roughnessMapIntensity = 0.9; // center 0.9 (spec says map multiplies)
      knotMat.needsUpdate = true;
    });
  }

  // Generate imperfection normal map (scratch noise) as a DataTexture
  (function addImperfection() {
    const size = 256;
    const data = new Uint8Array(size * size * 4);
    for (let i = 0; i < size * size; i++) {
      // Create a simple scratch-like pattern: random lines
      const val = Math.random() * 255;
      data[i*4] = val;
      data[i*4+1] = val;
      data[i*4+2] = 128; // Z component
      data[i*4+3] = 255;
    }
    const texture = new ctx.THREE.DataTexture(data, size, size, ctx.THREE.RGBAFormat, ctx.THREE.UnsignedByteType);
    texture.needsUpdate = true;
    knotMat.normalMap = texture;
    knotMat.normalScale = new Vector2(0.15, 0.15);
    knotMat.needsUpdate = true;
  })();

  // ----- Contact Shadow -----
  const shadowGeo = new CircleGeometry(1.5, 32);
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    blending: AdditiveBlending,
    depthWrite: false,
    side: DoubleSide
  });
  const shadowPos = positionGeometry;
  const dist = length(shadowPos.xy);
  const opacity = 0.6 * (1 - saturate(dist / 1.5));
  shadowMat.opacityNode = opacity;
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -0.36, 0);
  shadow.name = 'contact-shadow';
  group.add(shadow);

  // ----- Text: Headline -----
  const headlineObj = ctx.fontAtlas.createText('Material study 03', {
    fontSize: 68,
    fontWeight: 600,
    color: '#e8ecf2',
    align: 'center',
    letterSpacing: -0.005
  });
  headlineObj.position.set(0, -0.8, 0); // 1.2 units below knot center (0.4)
  headlineObj.name = 'headline';
  group.add(headlineObj);

  // ----- Text: Caption -----
  const captionObj = ctx.fontAtlas.createText('GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT', {
    fontSize: 18,
    fontWeight: 400,
    color: '#ff2a38',
    align: 'center',
    letterSpacing: 0.08
  });
  captionObj.position.set(0, -1.2, 0); // 1.6 units below knot center
  captionObj.name = 'caption';
  group.add(captionObj);

  // ----- Animation: knot rotation (0.1 rad/s) -----
  const knotRotateTimeline = gsap.to(knot.rotation, {
    y: Math.PI * 2,
    duration: 2 * Math.PI / 0.1, // period = 62.83s for 1 rad? Actually 0.1 rad/s, full rotation in 62.83s
    repeat: -1,
    ease: 'none'
  });

  // Apply cinematic primitives from config
  const primitivesCleanups = [];
  if (config.cinematicPrimitives) {
    for (const prim of config.cinematicPrimitives) {
      if (ctx.primitives && ctx.primitives[prim.name]) {
        const result = ctx.primitives[prim.name](group, prim.params);
        if (result && result.cleanup) primitivesCleanups.push(result.cleanup);
        if (result && result.timeline) ; // handle if needed
      }
    }
  }

  // Attach cleanup to userData
  group.userData.cleanup = () => {
    knotRotateTimeline.kill();
    // dispose geometries and materials
    gradBackdrop.dispose();
    gradMat.dispose();
    pedGeo.dispose();
    pedMat.dispose();
    knotGeo.dispose();
    knotMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    // dispose textures
    if (knotMat.roughnessMap) knotMat.roughnessMap.dispose();
    if (knotMat.normalMap) knotMat.normalMap.dispose();
    // dispose text meshes (they contain geometry and material)
    headlineObj.traverse((child) => {
      if (child.isMesh) {
        child.geometry.dispose();
        if (child.material) child.material.dispose();
      }
    });
    captionObj.traverse((child) => {
      if (child.isMesh) {
        child.geometry.dispose();
        if (child.material) child.material.dispose();
      }
    });
    // run primitive cleanups
    primitivesCleanups.forEach(fn => fn());
  };

  // Optional event handlers (none specified)
  group.userData.handlers = {};

  return group;
}
